(()=>{const t=window.BarfordMemberFlow,m=window.BarfordSupabase,a=document.getElementById("memberPayments"),n=new URLSearchParams(location.search).get("event");if(!t||!a)return;if(n){const r=document.getElementById("paymentBack");r.href=t.eventUrl(n),r.textContent="\u2190 Back to my event"}async function p(){try{const r=await t.request(m.auth.getSession());if(!r.session){a.innerHTML=`<article class="simple-card"><h2>Sign in to see your payments</h2><a class="button button-primary" href="${t.loginUrl(location.href)}">Sign in</a></article>`;return}const y=m.from("rsvps").select("event_id,status,payment_status").eq("member_id",r.session.user.id),c=await t.request(n?y.eq("event_id",n):y),h=n?[n]:c.filter(e=>e.status==="playing"||["paid","refunded","waived"].includes(e.payment_status)).map(e=>e.event_id);if(!h.length){a.innerHTML='<article class="simple-card"><h2>No event payments to show</h2><p>Your payments will appear here when you book an event.</p><a class="button button-primary" href="events.html">View events</a></article>';return}const o=await t.request(m.from("events").select("*").in("id",h).order("event_date"));if(!o.length){a.innerHTML='<article class="simple-card"><h2>Event not found</h2><a class="button button-outline" href="payments.html">View all my payments</a></article>';return}const s=t.paymentSummary(o,c),f=o.filter(e=>t.payment(e,c.find(i=>i.event_id===e.id)).due),l=o.filter(e=>!f.includes(e)),d=e=>{const i=c.find(b=>b.event_id===e.id),u=t.payment(e,i);return`<article class="simple-card payment-receipt"><p class="eyebrow">${t.esc(t.date(e.event_date))}</p><h2>${t.esc(e.name)}</h2><p class="simple-payment-state"><strong>${t.esc(u.label)}</strong></p>${u.due?"<p>Payment details are available from the committee. Your status changes to Paid when they confirm receipt.</p>":e.status==="cancelled"&&i?.payment_status==="paid"?"<p>Contact the committee to check your refund.</p>":i?.status==="reserve"?"<p>No payment is needed while you wait for a place.</p>":""}${u.due?`<button class="button button-primary full-button" data-payment-help="${t.esc(e.id)}">Get payment instructions</button><details class="simple-details"><summary>Already sent your payment?</summary><p>It has not been confirmed yet. Ask the committee to check before paying again.</p><button class="button button-outline" data-payment-check="${t.esc(e.id)}">Ask for confirmation</button></details>`:""}<a class="simple-back" href="${t.eventUrl(e.id)}">View event</a></article>`};a.innerHTML=`<section class="simple-card"><p class="eyebrow">${n?"This event":"My payments"}</p><h2>\xA3${(s.pence/100).toFixed(2)} outstanding</h2><p>${s.count?`${s.count} event${s.count===1?"":"s"} to pay.`:"No confirmed event fees outstanding."}${s.unpriced?` ${s.unpriced} booking${s.unpriced===1?" is":"s are"} awaiting a price.`:""}</p><button class="button button-outline" id="refreshPaymentStatus" type="button">Check payment status</button>${n?'<a class="simple-back" href="payments.html">All my payments</a>':""}</section>`+f.map(d).join("")+(l.length?n?l.map(d).join(""):`<details class="simple-card simple-details"><summary>Other bookings and payment history (${l.length})</summary><div class="simple-detail-content">${l.map(d).join("")}</div></details>`:""),a.querySelector("#refreshPaymentStatus").onclick=p,a.querySelectorAll("[data-payment-help],[data-payment-check]").forEach(e=>e.onclick=()=>t.contact(o.find(i=>i.id===(e.dataset.paymentHelp||e.dataset.paymentCheck)),e.dataset.paymentCheck?"check a payment I have already made":"get the payment details"))}catch{a.innerHTML='<article class="simple-card"><h2>Payments could not be checked</h2><p>Please try again to see the latest payment status.</p><button class="button button-primary" id="retryPayments">Try again</button></article>',a.querySelector("#retryPayments").onclick=p}}p()})();
